#[test]
fn max_message_bytes_limits_body_in_bytes_before_other_send_rules() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({"MaxMessageBytes": 4}));
    send(&mut h, "q", "abcd");
    send(&mut h, "q", "éé"); // 4 bytes, 2 characters
    let too_long = |body: &str| json!({"Command": "SendMessage", "QueueName": "q", "Body": body});
    assert_eq!(h.err(too_long("abcde")), "InvalidParameterValue");
    assert_eq!(h.err(too_long("ééa")), "InvalidParameterValue");
    // The size rule precedes rule 1 (UnsupportedOperation).
    assert_eq!(
        h.err(json!({"Command": "SendMessage", "QueueName": "q", "Body": "abcde", "GroupId": "g"})),
        "InvalidParameterValue"
    );
    // A missing queue still wins over it, and the 1024-byte rule over the queue's limit.
    assert_eq!(
        h.err(json!({"Command": "SendMessage", "QueueName": "nope", "Body": "abcde"})),
        "QueueDoesNotExist"
    );
}

#[test]
fn max_message_bytes_attribute_rules_and_existing_messages() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({}));
    let r = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert_eq!(r["Attributes"]["MaxMessageBytes"], 1024);
    for bad in [json!(0), json!(1025), json!("5"), json!(5.0)] {
        assert_eq!(
            h.err(json!({"Command": "SetQueueAttributes", "QueueName": "q",
                         "Attributes": {"MaxMessageBytes": bad}})),
            "InvalidParameterValue"
        );
    }
    // Takes part in CreateQueue's idempotence check.
    assert_eq!(
        h.err(json!({"Command": "CreateQueue", "QueueName": "q",
                     "Attributes": {"MaxMessageBytes": 10}})),
        "QueueAlreadyExists"
    );
    send(&mut h, "q", "0123456789");
    h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q",
                "Attributes": {"MaxMessageBytes": 5}}));
    let r = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert_eq!(r["Attributes"]["MaxMessageBytes"], 5);
    assert_eq!(bodies(&receive(&mut h, "q", 10)), ["0123456789"]);
    create(&mut h, "q", json!({"MaxMessageBytes": 5}));
}

#[test]
fn dead_letter_moves_ignore_max_message_bytes() {
    let mut h = Harness::new();
    create(&mut h, "dlq", json!({"MaxMessageBytes": 1}));
    create(&mut h, "q", json!({"DeadLetterQueue": "dlq", "MaxReceiveCount": 1,
                               "VisibilityTimeout": 0}));
    send(&mut h, "q", "long body");
    assert_eq!(receive(&mut h, "q", 1).len(), 1);
    assert!(receive(&mut h, "q", 1).is_empty());
    assert_eq!(bodies(&receive(&mut h, "dlq", 1)), ["long body"]);
}
