mod common;

use common::Harness;
use serde_json::{Value, json};

fn setup() -> Harness {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    h
}

fn tag(h: &mut Harness, tags: Value) -> Value {
    h.run(json!({"Command": "TagQueue", "QueueName": "q", "Tags": tags}))
}

fn tags(h: &mut Harness) -> Value {
    h.ok(json!({"Command": "ListQueueTags", "QueueName": "q"}))["Tags"].clone()
}

#[test]
fn new_queue_has_no_tags_and_set_replaces() {
    let mut h = setup();
    assert_eq!(tags(&mut h), json!({}));
    assert_eq!(tag(&mut h, json!({"a": "1", "b": ""})), json!({"ok": true}));
    assert_eq!(tag(&mut h, json!({"a": "2"})), json!({"ok": true}));
    assert_eq!(tags(&mut h), json!({"a": "2", "b": ""}));
    // Empty `Tags` is allowed; keys are case-sensitive.
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {}}));
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"A": "x"}}));
    assert_eq!(tags(&mut h), json!({"a": "2", "b": "", "A": "x"}));
}

#[test]
fn tag_value_and_key_validation() {
    let mut h = setup();
    assert_eq!(
        tag(&mut h, json!({"k": "é".repeat(128)}))["ok"],
        true,
        "256 bytes is allowed"
    );
    let too_long_bytes = "é".repeat(128) + "a";
    for bad in [
        json!({"k": too_long_bytes}),
        json!({"k": 1}),
        json!({"k": null}),
        json!({"": "v"}),
        json!({"a b": "v"}),
        json!({"k".repeat(129): "v"}),
    ] {
        let r = tag(&mut h, bad.clone());
        assert_eq!(r["error"]["code"], "InvalidParameterValue", "{bad}");
    }
    assert_eq!(tag(&mut h, json!({"k".repeat(128): "v"}))["ok"], true);
    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "q", "Tags": []})), "InvalidParameterValue");
    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "q"})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "q", "Tags": null})), "MissingParameter");
}

#[test]
fn check_order_is_values_then_lookup() {
    let mut h = setup();
    let cmd = |tags: Value| json!({"Command": "TagQueue", "QueueName": "nope", "Tags": tags});
    assert_eq!(h.err(cmd(json!({"k": 1}))), "InvalidParameterValue");
    assert_eq!(h.err(cmd(json!({"k": "v"}))), "QueueDoesNotExist");
    assert_eq!(h.err(json!({"Command": "ListQueueTags", "QueueName": "nope"})), "QueueDoesNotExist");
    assert_eq!(
        h.err(json!({"Command": "UntagQueue", "QueueName": "nope", "TagKeys": [1]})),
        "InvalidParameterValue"
    );
    assert_eq!(
        h.err(json!({"Command": "UntagQueue", "QueueName": "nope", "TagKeys": []})),
        "QueueDoesNotExist"
    );
}

#[test]
fn at_most_50_tags_and_failure_changes_nothing() {
    let mut h = setup();
    let fifty: serde_json::Map<String, Value> =
        (0..50).map(|i| (format!("k{i}"), json!("v"))).collect();
    assert_eq!(tag(&mut h, Value::Object(fifty))["ok"], true);
    // Replacing an existing key keeps the count at 50.
    assert_eq!(tag(&mut h, json!({"k0": "new"}))["ok"], true);
    let r = tag(&mut h, json!({"k0": "changed", "extra": "v"}));
    assert_eq!(r["error"]["code"], "LimitExceeded");
    let t = tags(&mut h);
    assert_eq!(t.as_object().unwrap().len(), 50);
    assert_eq!(t["k0"], "new");
    // Freeing one slot lets a new key in.
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["k1"]}));
    assert_eq!(tag(&mut h, json!({"extra": "v"}))["ok"], true);
}

#[test]
fn untag_ignores_unknown_keys() {
    let mut h = setup();
    tag(&mut h, json!({"a": "1", "b": "2"}));
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["a", "zzz", "a"]}));
    assert_eq!(tags(&mut h), json!({"b": "2"}));
    for bad in [json!(["a b"]), json!([""]), json!("a"), json!(["a", 1])] {
        assert_eq!(
            h.err(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": bad})),
            "InvalidParameterValue"
        );
    }
    assert_eq!(tags(&mut h), json!({"b": "2"}));
}

#[test]
fn tags_are_not_attributes_and_survive_purge_but_not_delete() {
    let mut h = setup();
    tag(&mut h, json!({"a": "1"}));
    let attrs = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert!(attrs["Attributes"].get("Tags").is_none());
    // CreateQueue rule 4 ignores tags.
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    h.ok(json!({"Command": "SendMessage", "QueueName": "q", "Body": "x"}));
    h.ok(json!({"Command": "PurgeQueue", "QueueName": "q"}));
    assert_eq!(tags(&mut h), json!({"a": "1"}));
    h.ok(json!({"Command": "DeleteQueue", "QueueName": "q"}));
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    assert_eq!(tags(&mut h), json!({}));
}
